CREATE TABLE "public"."atualizar" (
  "id"         bigint                   GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "public"."bd_ativo_id_seq") NOT NULL,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  "numero"     bigint,
  CONSTRAINT "bd_ativo_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."atualizar"
  ENABLE ROW LEVEL SECURITY;

CREATE POLICY "atualizar_no_direct_access" ON "public"."atualizar"
  FOR ALL
  TO "authenticated"
  USING (false)
  WITH CHECK (false);

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."atualizar" TO "postgres", "service_role";
